const items = db.prepare(\"SELECT ci.quantity, COALESCE(p.current_price, p.price) as effective_price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.customer_id='user_58b0a2d6'\").all();
let subtotal = 0;
for (const i of items) {
  subtotal += i.quantity * i.effective_price;
  console.log('Item: qty=' + i.quantity + ' price=' + i.effective_price + ' line=' + (i.quantity * i.effective_price));
}
console.log('New subtotal:', subtotal);

// Update cart totals and item_ids_json
const cart = db.prepare(\"SELECT * FROM carts WHERE customer_id='user_58b0a2d6'\").get();
const newTotal = subtotal - (cart.discount_amount || 0) + (cart.gift_wrap_fee || 0) - (cart.loyalty_discount || 0) + (cart.shipping_cost || 0);

const remainingIds = items.length > 0 
  ? JSON.parse(cart.item_ids_json).filter(id => id !== 'CI-0007')
  : [];

db.prepare(\"UPDATE carts SET subtotal=?, total=?, item_ids_json=? WHERE customer_id='user_58b0a2d6'\").run(subtotal, newTotal, JSON.stringify(remainingIds));

// Verify
const updatedCart = db.prepare(\"SELECT * FROM carts WHERE customer_id='user_58b0a2d6'\").get();
const updatedItems = db.prepare(\"SELECT ci.cart_item_id, ci.quantity, p.name, COALESCE(p.current_price, p.price) as price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.customer_id='user_58b0a2d6'\").all();
console.log('\nUpdated cart:', JSON.stringify(updatedCart, null, 2));
console.log('Remaining items:');
for (const i of updatedItems) console.log(JSON.stringify(i));

db.close();
